    for (int i = 0; i < n; i++) {
        cin >> h[i];
    }

    int lo = 0, hi = n - 1;
    long long max_area = 0;

    while (lo < hi) {
        long long width = hi - lo;
        long long current_height = min(h[lo], h[hi]);
        long long area = width * current_height;
