using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string s;
    int k;
    if (!(cin >> s >> k)) return 0;

    unordered_map<char, int> freq;
    int lo = 0;
    int max_len = 0;

    for (int hi = 0; hi < (int)s.size(); hi++) {
        freq[s[hi]]++;

        // Shrink left until distinct count <= k
        while ((int)freq.size() > k && lo <= hi) {
            freq[s[lo]]--;
            if (freq[s[lo]] == 0) {
                freq.erase(s[lo]);
            }
            lo++;
        }

        max_len = max(max_len, hi - lo + 1);
    }

    cout << max_len << "\n";
    return 0;
}

